# Define a custom function inheriting from InplaceFunction
class MyInplaceOp(InplaceFunction):
    @staticmethod
    def forward(ctx, x, inplace=False):
        if inplace:
            x.add_(1.0)  # in-place modification
            ctx.mark_dirty(x)
        else:
            x = x + 1.0
        ctx.mark_non_differentiable(x if inplace else x)  # ensure output is not differentiable if in-place
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output, None

